// Lade gespeicherte Config oder nutze Standardwerte
let config = global.get('smart_charging_config') || {};

// Setze Standardwerte falls nicht vorhanden
config = {
    // Grundeinstellungen
    enabled: config.enabled !== undefined ? config.enabled : false,
    min_charge_current: config.min_charge_current || 7,
    max_charge_current: config.max_charge_current || 32,
    phases: config.phases || 3,
    hysteresis_time: config.hysteresis_time || 2, // Minuten

    // Batterie-Einstellungen
    battery_priority: config.battery_priority !== undefined ? config.battery_priority : true,
    min_battery_soc: config.min_battery_soc || 95, // Erst ab 95% SOC Auto laden
    prevent_battery_discharge: config.prevent_battery_discharge !== undefined ? config.prevent_battery_discharge : true,
    max_grid_power_draw: config.max_grid_power_draw || 500, // Max 500W aus Netz wenn Batterie nicht entladen werden soll

    // Auto-Einstellungen
    car_target_soc: config.car_target_soc || 80,
    car_soc_threshold_pure_surplus: config.car_soc_threshold_pure_surplus || 80, // Ab 80% nur reiner Überschuss

    // Überbrückungslogik
    bridge_enabled: config.bridge_enabled !== undefined ? config.bridge_enabled : true,
    bridge_max_duration: config.bridge_max_duration || 10, // Minuten
    bridge_min_current: config.bridge_min_current || 7, // Ampere
    bridge_notification: config.bridge_notification !== undefined ? config.bridge_notification : true,

    // Tibber-Preissteuerung
    tibber_enabled: config.tibber_enabled !== undefined ? config.tibber_enabled : false,
    tibber_price_threshold: config.tibber_price_threshold || 0.15, // 15 Cent/kWh
    tibber_charge_current: config.tibber_charge_current || 16,

    // Minimaler Überschuss zum Starten
    min_surplus_to_start: config.min_surplus_to_start || 4800, // 7A * 230V * 3 Phasen
    min_surplus_to_continue: config.min_surplus_to_continue || 3000, // Zum Weiterladen reichen 3kW

    // Manuelle Übersteuerung
    override_mode: config.override_mode || 'auto', // auto, force_charge, force_stop, pv_only
    override_charge_current: config.override_charge_current || 16, // Strom bei force_charge

    // Status
    last_update: new Date().toISOString(),
    charging_mode: config.charging_mode || 'idle' // idle, pv_surplus, bridge, tibber_price
};

global.set('smart_charging_config', config);
msg.payload = config;
return msg;

if (msg.data && msg.data.entity_id) {
    msg.payload = {
        entity: msg.data.entity_id,
        value: msg.payload,
        unit: msg.data.new_state ? msg.data.new_state.attributes.unit_of_measurement : ''
    };
}
return msg;

// Hole alle aktuellen States aus Home Assistant
const entities = [
    'sensor.rct_power_storage_grid_power',
    'sensor.rct_power_storage_battery_state_of_charge',
    'sensor.rct_power_storage_battery_power',
    'sensor.rct_power_storage_inverter_ac_power',
    'sensor.rct_power_storage_consumer_power',
    'sensor.easee_home_power',
    'sensor.easee_home_maximum_allowed_charge_current',
    'binary_sensor.easee_home_charging',
    'sensor.zoe_battery',
    'sensor.zoe_plug_state',
    'sensor.zoe_charge_state'
];

// Speichere den aktuellen State
let sensorData = global.get('sensor_data') || {};

// Update den State für diese Entity
if (msg.data && msg.data.entity_id) {
    sensorData[msg.data.entity_id] = {
        state: msg.payload,
        attributes: msg.data.new_state ? msg.data.new_state.attributes : {},
        last_updated: new Date().toISOString()
    };
}

global.set('sensor_data', sensorData);

// Prüfe ob alle wichtigen Daten vorhanden sind
const hasAllData = entities.every(entity => sensorData[entity]);

if (hasAllData) {
    // Erstelle strukturiertes Datenobjekt
    msg.payload = {
        rct: {
            grid_power: parseFloat(sensorData['sensor.rct_power_storage_grid_power'].state) || 0,
            battery_soc: parseFloat(sensorData['sensor.rct_power_storage_battery_state_of_charge'].state) || 0,
            battery_power: parseFloat(sensorData['sensor.rct_power_storage_battery_power'].state) || 0,
            inverter_power: parseFloat(sensorData['sensor.rct_power_storage_inverter_ac_power'].state) || 0,
            consumer_power: parseFloat(sensorData['sensor.rct_power_storage_consumer_power'].state) || 0
        },
        easee: {
            power: parseFloat(sensorData['sensor.easee_home_power'].state) || 0,
            current: parseFloat(sensorData['sensor.easee_home_maximum_allowed_charge_current'].state) || 0,
            charging: sensorData['binary_sensor.easee_home_charging'].state === 'on'
        },
        zoe: {
            battery: parseFloat(sensorData['sensor.zoe_battery'].state) || 0,
            plug_state: sensorData['sensor.zoe_plug_state'].state,
            charge_state: sensorData['sensor.zoe_charge_state'].state
        },
        timestamp: new Date().toISOString()
    };

    return msg;
}

return null;

const config = global.get('smart_charging_config');
const data = msg.payload;

// === MANUELLE ÜBERSTEUERUNG ===
if (config && config.override_mode && config.override_mode !== 'auto') {
    if (config.override_mode === 'force_stop') {
        msg.payload.control = {
            action: 'stop',
            reason: '🛑 Manuell gestoppt (Override)'
        };
        msg.payload.override_active = true;
        return msg;
    }

    if (config.override_mode === 'force_charge') {
        msg.payload.control = {
            action: 'force_charge',
            reason: '⚡ Manuelles Laden erzwungen (Override)',
            target_current: config.override_charge_current || 16
        };
        msg.payload.override_active = true;
        return msg;
    }

    // pv_only: Deaktiviert Überbrückung und Tibber, nur PV-Überschuss
    if (config.override_mode === 'pv_only') {
        msg.payload.override_pv_only = true;
    }
}

// Prüfe ob System aktiv ist
if (!config || !config.enabled) {
    msg.payload.control = {
        action: 'stop',
        reason: 'System deaktiviert'
    };
    return msg;
}

// Prüfe ob Auto angeschlossen ist
const carPluggedIn = data.zoe.plug_state === 'Plugged in' || data.zoe.plug_state === 'plugged';
if (!carPluggedIn) {
    msg.payload.control = {
        action: 'stop',
        reason: 'Fahrzeug nicht angeschlossen'
    };
    return msg;
}

// Prüfe ob Ziel-SOC erreicht
if (data.zoe.battery >= config.car_target_soc) {
    msg.payload.control = {
        action: 'stop',
        reason: `Ziel-SOC ${config.car_target_soc}% erreicht`
    };
    return msg;
}

// Berechne verfügbaren Überschuss
// Negatives grid_power = Einspeisung ins Netz
// Positives grid_power = Bezug aus dem Netz
// Negatives battery_power = Batterie wird geladen

let available_surplus = 0;

// Wenn Batterie-Priorität aktiviert und Batterie noch nicht voll genug
if (config.battery_priority && data.rct.battery_soc < config.min_battery_soc) {
    msg.payload.control = {
        action: 'stop',
        reason: `Batterie-Priorität: SOC ${data.rct.battery_soc}% < ${config.min_battery_soc}%`
    };
    return msg;
}

// Berechne Überschuss
if (data.rct.grid_power < 0) {
    // Es wird eingespeist
    available_surplus = Math.abs(data.rct.grid_power);

    // Addiere aktuelle Wallbox-Leistung falls schon am Laden
    if (data.easee.charging && data.easee.power > 0) {
        available_surplus += data.easee.power;
    }
} else {
    // Es wird bezogen
    if (data.easee.charging && data.easee.power > 0) {
        // Wenn bereits geladen wird, berechne was übrig wäre ohne Wallbox
        available_surplus = data.easee.power - data.rct.grid_power;
    } else {
        available_surplus = -data.rct.grid_power; // Negativ = kein Überschuss
    }
}

// Wenn Batterie-Entladung verhindert werden soll
if (config.prevent_battery_discharge && data.rct.battery_power > 0) {
    // Batterie wird entladen (positive Werte = Entladung)
    // Reduziere verfügbaren Überschuss um Batterie-Entladung
    available_surplus -= data.rct.battery_power;
}

// Speziallogik: Ab Car-SOC-Threshold nur reiner Überschuss (keine Batterie-Entladung)
if (data.zoe.battery >= config.car_soc_threshold_pure_surplus) {
    // Strenge Prüfung: Nur laden wenn wirklich Überschuss da ist
    if (data.rct.grid_power > config.max_grid_power_draw || data.rct.battery_power > 100) {
        msg.payload.control = {
            action: 'stop',
            reason: `Auto-SOC ${data.zoe.battery}% >= ${config.car_soc_threshold_pure_surplus}%: Nur reiner Überschuss erlaubt`
        };
        return msg;
    }
}

msg.payload.calculated = {
    available_surplus: Math.round(available_surplus),
    grid_power: data.rct.grid_power,
    battery_power: data.rct.battery_power,
    battery_soc: data.rct.battery_soc,
    current_charging_power: data.easee.power
};

return msg;

const config = global.get('smart_charging_config');
const data = msg.payload;

// === OVERRIDE: Manuelles Laden ===
if (data.control && data.control.action === 'force_charge') {
    // Erzwinge Laden mit festem Strom
    msg.payload.control.calculated_power = Math.round(data.control.target_current * 230 * Math.sqrt(3) * config.phases);
    return [null, msg, null, null]; // Start + Adjust Current
}

// Wenn Stop-Action bereits gesetzt, durchreichen
if (data.control && data.control.action === 'stop') {
    return [msg, null, null, null];
}

const surplus = data.calculated.available_surplus;
const isCharging = data.easee.charging;

// Lade oder erstelle Charging-State
let chargingState = global.get('charging_state') || {
    mode: 'idle',
    bridge_start_time: null,
    last_current_change: null,
    last_current: 0
};

// Funktion: Berechne benötigten Strom aus Leistung
function calculateCurrent(power_watts) {
    // 3-Phasen: P = U * I * sqrt(3) * 3
    // I = P / (230 * 1.732 * 3) = P / 1195
    const voltage = 230;
    const phases = config.phases;
    let current;

    if (phases === 3) {
        current = power_watts / (voltage * Math.sqrt(3) * phases);
    } else {
        current = power_watts / voltage;
    }

    return Math.floor(current);
}

// Funktion: Berechne Leistung aus Strom
function calculatePower(current_ampere) {
    const voltage = 230;
    const phases = config.phases;

    if (phases === 3) {
        return current_ampere * voltage * Math.sqrt(3) * phases;
    } else {
        return current_ampere * voltage;
    }
}

// Prüfe Tibber-Preis-Modus (falls aktiviert)
// TODO: Tibber Sensor einbinden wenn gewünscht
const tibberPriceMode = false; // Später implementieren mit Tibber Sensor

let targetCurrent = 0;
let newMode = chargingState.mode;
let action = 'hold';
let reason = '';

// === MODUS 1: Tibber Günstig-Laden ===
if (config.tibber_enabled && tibberPriceMode) {
    targetCurrent = config.tibber_charge_current;
    newMode = 'tibber_price';
    action = 'charge';
    reason = 'Tibber-Preis unter Schwellenwert';
}
// === MODUS 2: PV-Überschuss ===
else {
    // Berechne Zielstrom aus Überschuss
    let calculatedCurrent = calculateCurrent(surplus);

    // Wenn aktuell geladen wird
    if (isCharging) {
        // Prüfe ob genug Überschuss zum Weiterladen
        if (surplus >= config.min_surplus_to_continue) {
            targetCurrent = Math.max(config.min_charge_current, 
                            Math.min(config.max_charge_current, calculatedCurrent));
            newMode = 'pv_surplus';
            action = 'charge';
            reason = `PV-Überschuss: ${surplus}W`;
        } else {
            // Überschuss zu gering - Überbrückung?
            // PV-Only Override deaktiviert Überbrückung
            const bridgeAllowed = config.bridge_enabled && !data.override_pv_only;
            if (bridgeAllowed) {
                // Starte oder prüfe Überbrückung
                if (!chargingState.bridge_start_time) {
                    chargingState.bridge_start_time = Date.now();
                }

                const bridgeMinutes = (Date.now() - chargingState.bridge_start_time) / 1000 / 60;

                if (bridgeMinutes < config.bridge_max_duration) {
                    targetCurrent = config.bridge_min_current;
                    newMode = 'bridge';
                    action = 'charge';
                    reason = `Überbrückung: ${Math.round(bridgeMinutes)}/${config.bridge_max_duration} Min`;

                    // Notification senden (nur einmal)
                    if (!chargingState.bridge_notification_sent && config.bridge_notification) {
                        msg.notification = {
                            message: `Ladestrom auf ${config.bridge_min_current}A reduziert (Überbrückung)`,
                            title: 'Smartes Laden: Überbrückung aktiv'
                        };
                        chargingState.bridge_notification_sent = true;
                    }
                } else {
                    // Überbrückungszeit abgelaufen
                    action = 'stop';
                    newMode = 'idle';
                    reason = 'Überbrückungszeit abgelaufen';
                    chargingState.bridge_start_time = null;
                    chargingState.bridge_notification_sent = false;
                }
            } else {
                // Keine Überbrückung - stoppen
                action = 'stop';
                newMode = 'idle';
                reason = 'Überschuss zu gering';
            }
        }
    } else {
        // Aktuell wird nicht geladen - prüfe ob Start möglich
        if (surplus >= config.min_surplus_to_start) {
            targetCurrent = Math.max(config.min_charge_current, 
                            Math.min(config.max_charge_current, calculatedCurrent));
            newMode = 'pv_surplus';
            action = 'start';
            reason = `Start: ${surplus}W Überschuss verfügbar`;

            // Reset Bridge-State
            chargingState.bridge_start_time = null;
            chargingState.bridge_notification_sent = false;
        } else {
            action = 'hold';
            newMode = 'idle';
            reason = `Warte auf Überschuss (${surplus}W < ${config.min_surplus_to_start}W)`;
        }
    }
}

// Hysterese-Prüfung für Stromänderungen
const now = Date.now();
if (chargingState.last_current_change) {
    const minutesSinceChange = (now - chargingState.last_current_change) / 1000 / 60;
    if (minutesSinceChange < config.hysteresis_time && 
        Math.abs(targetCurrent - chargingState.last_current) <= 2) {
        // Zu früh für Änderung, behalte alten Wert
        targetCurrent = chargingState.last_current;
        reason += ' (Hysterese aktiv)';
    }
}

// Update Charging State
if (targetCurrent !== chargingState.last_current) {
    chargingState.last_current_change = now;
    chargingState.last_current = targetCurrent;
}

chargingState.mode = newMode;
global.set('charging_state', chargingState);

// Erstelle Control-Message
msg.payload.control = {
    action: action,
    target_current: targetCurrent,
    mode: newMode,
    reason: reason,
    calculated_power: Math.round(calculatePower(targetCurrent))
};

// Route zu entsprechendem Output
if (action === 'stop') {
    return [msg, null, null, null]; // Output 1: Stop
} else if (action === 'start') {
    return [null, msg, null, null]; // Output 2: Start
} else if (action === 'charge') {
    return [null, null, msg, null]; // Output 3: Adjust Current
} else {
    return [null, null, null, msg]; // Output 4: Hold/Idle
}

const control = msg.payload.control;
const data = msg.payload;

// Erstelle Log-Eintrag
const logEntry = {
    timestamp: new Date().toISOString(),
    action: control.action,
    mode: control.mode,
    reason: control.reason,
    target_current: control.target_current || 0,
    calculated_power: control.calculated_power || 0,
    available_surplus: data.calculated ? data.calculated.available_surplus : 0,
    battery_soc: data.rct.battery_soc,
    car_soc: data.zoe.battery
};

// Speichere letzte 100 Log-Einträge
let logs = global.get('charging_logs') || [];
logs.unshift(logEntry);
if (logs.length > 100) logs = logs.slice(0, 100);
global.set('charging_logs', logs);

// Update Status für Dashboard
const status = {
    enabled: global.get('smart_charging_config').enabled,
    mode: control.mode,
    action: control.action,
    current_charging: data.easee.charging,
    target_current: control.target_current,
    available_surplus: data.calculated ? data.calculated.available_surplus : 0,
    battery_soc: data.rct.battery_soc,
    car_soc: data.zoe.battery,
    last_update: new Date().toISOString(),
    reason: control.reason
};

global.set('charging_status', status);

msg.payload = logEntry;
return msg;

let config = global.get('smart_charging_config') || {};
config.override_mode = 'auto';
global.set('smart_charging_config', config);
msg.payload = {mode: 'auto', info: 'Automatische Steuerung aktiv'};
return msg;

let config = global.get('smart_charging_config') || {};
config.override_mode = 'force_charge';
config.override_charge_current = 16; // Anpassbar!
global.set('smart_charging_config', config);
msg.payload = {mode: 'force_charge', current: 16, info: 'Laden mit 16A erzwungen'};
return msg;

let config = global.get('smart_charging_config') || {};
config.override_mode = 'force_stop';
global.set('smart_charging_config', config);
msg.payload = {mode: 'force_stop', info: 'Laden gestoppt (Override aktiv)'};
return msg;

let config = global.get('smart_charging_config') || {};
config.override_mode = 'pv_only';
global.set('smart_charging_config', config);
msg.payload = {mode: 'pv_only', info: 'Nur reiner PV-Überschuss, keine Überbrückung/Tibber'};
return msg;
